package org.sleepwell.app;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class ChallengeRoutineTest {
    private ChallengeRoutine.Task task(String type,int rounds){return new ChallengeRoutine.Task(type,rounds);}
    @Test public void legacyRepeatedQuestionTasksKeepEveryRound(){for(String type:List.of("Math","Memory","Sequence","Retype")){ChallengeRoutine routine=ChallengeRoutine.legacy(type,4);assertEquals(4,routine.units());for(int n=0;n<4;n++){assertEquals(type,routine.at(n).task.type);assertEquals(n,routine.at(n).round);}assertNull(routine.at(4));}}
    @Test public void legacyPhysicalTasksKeepTheirOriginalSingleUnitAndTarget(){ChallengeRoutine shake=ChallengeRoutine.legacy("Shake",4),nfc=ChallengeRoutine.legacy("NFC",4);assertEquals(1,shake.units());assertEquals("20 shakes",shake.at(0).task.detail());assertEquals(1,nfc.units());assertEquals("Enrolled morning tag",nfc.at(0).task.detail());}
    @Test public void mixedTasksOnlyFinishAfterEveryStepAndRound(){ChallengeRoutine routine=new ChallengeRoutine(List.of(task("Math",2),task("Shake",3),task("NFC",1),task("Retype",2)));assertEquals(6,routine.units());String[] order={"Math","Math","Shake","NFC","Retype","Retype"};int completed=0;for(String expected:order){assertNotNull(routine.at(completed));assertEquals(expected,routine.at(completed).task.type);completed=routine.advance(completed,completed);}assertNull(routine.at(completed));}
    @Test public void shakeAndNfcSuccessCannotDismissFollowingTasks(){ChallengeRoutine routine=new ChallengeRoutine(List.of(task("Shake",2),task("NFC",1),task("Math",1)));int afterShake=routine.advance(0,0);assertEquals("NFC",routine.at(afterShake).task.type);int afterNfc=routine.advance(afterShake,afterShake);assertEquals("Math",routine.at(afterNfc).task.type);assertNull(routine.at(routine.advance(afterNfc,afterNfc)));}
    @Test public void duplicateOrStaleSuccessDoesNotSkipARound(){ChallengeRoutine routine=ChallengeRoutine.legacy("Math",3);assertEquals(1,routine.advance(0,0));assertEquals(1,routine.advance(1,0));assertEquals(1,routine.advance(1,2));assertEquals(3,routine.advance(3,3));assertEquals(0,routine.advance(0,-1));}
    @Test public void reopeningPersistedCountRestoresTaskAndRound(){ChallengeRoutine routine=new ChallengeRoutine(List.of(task("Math",2),task("Memory",3),task("Retype",1)));ChallengeRoutine.Position reopened=routine.at(3);assertEquals(1,reopened.index);assertEquals(1,reopened.round);assertEquals("Memory",reopened.task.type);}
    @Test public void reorderAndRemoveAreImmutableAndKeepConfiguration(){ChallengeRoutine original=new ChallengeRoutine(List.of(task("Math",3),task("Shake",4),task("Retype",2)));ChallengeRoutine reordered=original.move(2,0);assertEquals("Retype",reordered.tasks.get(0).type);assertEquals(2,reordered.tasks.get(0).rounds);assertEquals("Math",original.tasks.get(0).type);ChallengeRoutine removed=reordered.remove(1);assertEquals(2,removed.tasks.size());assertEquals("Shake",removed.tasks.get(1).type);assertEquals(4,removed.tasks.get(1).rounds);assertEquals(3,original.tasks.size());}
    @Test public void editingOneStepDoesNotChangeOtherSteps(){ChallengeRoutine routine=new ChallengeRoutine(List.of(task("Math",3),task("Memory",2)));ChallengeRoutine edited=routine.replace(1,task("Memory",5));assertEquals(3,edited.tasks.get(0).rounds);assertEquals(5,edited.tasks.get(1).rounds);assertEquals(2,routine.tasks.get(1).rounds);}
    @Test public void invalidLegacyTypeKeepsExistingMathFallback(){assertEquals("Math",ChallengeRoutine.legacy("OldUnknownType",3).at(0).task.type);assertEquals(3,ChallengeRoutine.legacy("OldUnknownType",3).units());}
    @Test public void emptyAndOversizedAndUnsupportedConfigurationAreRejected(){assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine(List.of()));assertThrows(IllegalArgumentException.class,()->task("QR",1));assertThrows(IllegalArgumentException.class,()->task("Math",0));assertThrows(IllegalArgumentException.class,()->task("Math",7));List<ChallengeRoutine.Task> tasks=new ArrayList<>();for(int n=0;n<8;n++)tasks.add(task("Math",6));ChallengeRoutine full=new ChallengeRoutine(tasks);assertEquals(48,full.units());assertThrows(IllegalArgumentException.class,()->full.add(task("Math",1)));assertThrows(IllegalArgumentException.class,()->ChallengeRoutine.legacy("Math",1).remove(0));}
}
